// FIRE page fixtures (stage-6.md §3.6): typed, generic `GET /api/fire` responses for the UI tests,
// one per state the page draws, plus the recorded projection inputs of each (`fireFixtureInputs`),
// so a server test (gated by FIRE_ENGINE_IMPLEMENTED) can check that `projectFire` reproduces every
// fixture within 1 cent. Generated by the Scaffolder from the plan-reviser's model of §2.5 (in
// doubles, rounded once to cents); generic round numbers only. `onTrack` is the hand-worked
// example of §10.1. The web builds the what-if failure state from the error fixtures.
import type { SettingsPatchResponse } from '../dto/cashflow';
import type { FirePageResponse } from '../dto/fire';
import type { DecimalString, IsoDate } from '../primitives';

/** `FireProjectionInput` (@joinr/engine) as JSON: Cents → number. */
export interface FireFixtureProjectionInput {
  asOf: IsoDate;
  birthYear: number | null;
  accessAge: number | null;
  inflationRatio: DecimalString | null;
  withdrawalRatio: DecimalString | null;
  preSuperCents: number;
  preSuperDebtCents: number;
  superCents: number;
  savingsPerYearCents: number | null;
  extraSavingsPerYearCents: number;
  superContributionPerYearCents: number;
  yearlySpendCents: number | null;
  growth: {
    cashWeightCents: number;
    marketWeightCents: number;
    cashInterestRatio: DecimalString | null;
    marketReturnRatio: DecimalString | null;
  };
  horizonAge?: number;
}

